float random(float seed)
{
    return fract(57128.836 * sin(dot(vec2(seed), vec2(12.77251, 72.37871))));
}

float block_size = 15.0;
float glitch_intensity = 0.6;
float glitch_speed = 5.0;
float color_glitch = 0.04;
float glitch_rate = 0.3; //shake rate
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    float enable_glitch = float(random(floor(iTime * glitch_speed)) < glitch_rate);
    float offset = (random(floor(uv.y * block_size)+iTime) - 0.5) * glitch_intensity * enable_glitch;
    vec2 fixed_uv = offset + uv;

    vec3 color = texture(iChannel0, fixed_uv).rgb;

    color.r = mix(color.r, texture(iChannel0, fixed_uv + vec2(color_glitch, 0.0)).r, enable_glitch);
    color.b = mix(color.b, texture(iChannel0, fixed_uv - vec2(color_glitch, 0.0)).b, enable_glitch);

    // Output to screen
    fragColor = vec4(color, 1.0);
}
